export function getHeroIcon(name: string, type: 'outline' | 'solid' = 'outline', color = '#111827', strokeWidth = 1.5): string {
    const map = type === 'solid' ? SOLID_ICONS : OUTLINE_ICONS;
    let svg = map[name];
    if (!svg) {
        return `~/assets/heroicons/${type === 'solid' ? '24/solid' : '24/outline'}/${name}.svg`;
    }
    if (type === 'outline') {
        svg = svg.replace(/stroke="[^"]*"/g, `stroke="${color}"`);
        if (strokeWidth !== 1.5) {
            svg = svg.replace(/stroke-width="[^"]*"/g, `stroke-width="${strokeWidth}"`);
        }
    } else {
        svg = svg.replace(/fill="[^"]*"/g, `fill="${color}"`);
    }
    return svg;
}
